code='''def transform(grid):
    h,w=len(grid),len(grid[0])
    counts={v:sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    bg=max(counts,key=counts.get)
    other=[v for v in counts if v!=bg]
    color=max(other,key=counts.get)
    out=[row[:] for row in grid]
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==color]
        if len(cs)>=2:
            for c in range(min(cs),max(cs)+1):
                if out[r][c]==bg: out[r][c]=2
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==color]
        if len(rs)>=2:
            for r in range(min(rs),max(rs)+1):
                if out[r][c]==bg: out[r][c]=2
    return out
'''
